INSERT INTO "jobs" VALUES('saramin','https://www.saramin.co.kr/zf_user/jobs/relay/view?rec_idx=55508690','{"collected_at":"2026-11-07T00:00:42.997073+00:00","company":"(주)코리아파트너즈","deadline":"2026-12-06","description":"[정규직/경력무관] 경영기획 채용( 인사 )/총무 담당자 모집 스크랩 ~ 12/06(일) 입사지원 서울 중구 경력무관 초대졸↑ 정규직 인사 , 인력관리 , 경영지원 , 채용담당자 , 채용공고관리 외 등록일 26/11/06 (주)코리아파트너즈 관심기업 등록 관심기업 등록 기업정보 공고 모아보기 +","employment_type":"","experience":"","keyword":"인사","link":"https://www.saramin.co.kr/zf_user/jobs/relay/view?rec_idx=55508690","location":"서울 중구","matched_keywords":["인사"],"site":"saramin","source_url":"https://www.saramin.co.kr/zf_user/search/recruit?searchType=search&searchword=%EC%9D%B8%EC%82%AC&recruitPage=2","title":"[정규직/경력무관] 경영기획 채용( 인사 )/총무 담당자 모집"}','a87791c024269b818a234735678b613a7d925de1156dcd376ef21648565581e6','2026-11-07T00:01:37+00:00','2026-11-07T00:01:37+00:00','2026-11-07T00:01:37+00:00');
