INSERT INTO "jobs" VALUES('wanted','https://www.wanted.co.kr/wd/379544','{"collected_at":"2026-11-07T00:01:11.134022+00:00","company":"케이엠 컬렉티브","deadline":"","description":"FIELD DIGITAL EDITOR (주요업무) • 패션/뷰티/라이프스타일 행사, 브랜드 이벤트, 문화공간, 전시, 레스토랑 등 현장 취재 • UGC 스타일의 자연스럽고 몰입도 높은 콘텐츠 제작 • 대한민국 컬쳐/트렌드/라이프스타일/F&B/패션/뷰티/여행 등 관련 SNS 콘텐츠 제작 • 대한민국 분야별 컬처/트렌드를 이끄는 인물 인터뷰 영상 콘텐츠 제작 • SNS 채널 콘텐츠 업로드 및 운영 • 월간 에디토리얼 캘린더 기획 • 외국인을 위한 문화적 맥락 설명 콘텐츠 제작 • Branded 프로젝트 협업 • 브랜드, PR, 에이전시와 커뮤니케이션 • FIELD DIGITAL EDITOR (Key Responsibilities) • Visit cultural sites, restaurants, exhibitions, fashion events, festivals, and brand activations for on-site coverage • Capture and produce photo editorials and short-form mobile video content (Reels, Shorts, TikTok-style content) • Create UGC-style storytelling that feels authentic and culturally immersive • Cover K-culture events including lifestyle, fashion, beauty, food, travel, K-pop and K-drama-related happenings • Edit and publish visual content across social media platforms • Collaborate with Creative Director and editorial team for branded campaigns • Communicate with brands, PR agencies, and event organizers 미디어, 에디터, 콘텐츠 크리에이터, 콘텐츠 에디터","employment_type":"regular","experience":"경력 1년+ / 정규직","keyword":"문화","link":"https://www.wanted.co.kr/wd/379544","location":"한국 서울 강남구 서울 강남구 테헤란로 231","matched_keywords":["문화"],"site":"wanted","source_url":"https://www.wanted.co.kr/api/chaos/search/v1/position?query=%EB%AC%B8%ED%99%94&country=kr&years=-1&locations=all&sort=job.recommend_order&limit=20&offset=0","title":"Digital editor - K.O.Magazine [경력 1년+ / 정규직]"}','8f3efd8ce53a702f936d2bf6e0d98309e698a03ec4cfee815f0cd1394fcce8fb','2026-10-17T17:35:26+00:00','2026-11-07T00:01:37+00:00','2026-10-17T17:35:26+00:00');
