INSERT INTO "jobs" VALUES('wanted','https://www.wanted.co.kr/wd/396335','{"collected_at":"2026-11-07T00:01:17.880290+00:00","company":"아마존(Amazon)","deadline":"","description":"• Operate and develop industry-academia collaboration education programs to build a sustainable talent pipeline for data center operations roles • Design and iterate on training curricula for data center talent development, collaborating with subject matter experts across operations and engineering teams • Manage end-to-end program operations including partner institution coordination, candidate recruitment, curriculum development, evaluation, and program improvement • Coordinate with multiple internal stakeholders (Recruiting, HR, Operations, Engineering) and external partners (universities, technical colleges, training institutions) to ensure program alignment and effectiveness • Track program metrics (e.g., candidate conversion rates, training completion, time-to-productivity) and drive continuous improvement • Own and operate the in-house English language program for employees who need English proficiency support • Manage relationships with external language education vendors, including vendor selection, contract management, program scheduling, and quality assurance • Design program structure (levels, cohorts, schedules) based on employee needs assessment • Monitor program participation, progress, and outcomes; report on ROI and effectiveness • Operate and support new hire training and onboarding programs, ensuring a smooth and engaging experience for all new employees • Coordinate and facilitate New Hire Orientation (NHO) sessions and manage cohort-based onboarding programs across multiple sites • Maintain and continuously improve onboarding materials, training content, and support resources • Plan and execute a career mentoring program targeting students interested in the data center industry • Research and identify external training programs, courses, and resources that meet the organization''s skill development needs • Plan and execute social contribution (CSR) education programs in partnership with diverse external organizations including libraries, schools, local government, NGOs, and community institutions HR, 기술 교육, HRD, E-러닝","employment_type":"regular","experience":"경력 2년+ / 정규직","keyword":"HRD","link":"https://www.wanted.co.kr/wd/396335","location":"한국 서울 강남구 서울특별시 강남구 테헤란로 231 (역삼동, 센터필드 서관 12층)","matched_keywords":["HRD"],"site":"wanted","source_url":"https://www.wanted.co.kr/api/chaos/search/v1/position?query=HRD&country=kr&years=-1&locations=all&sort=job.recommend_order&limit=20&offset=0","title":"DCO Program Tech – L&D Specialist People with Disability (PwD), ICN [경력 2년+ / 정규직]"}','8c7cedadcb5f6fb3c69c94fc6fcc587deca98e81872f927fededdba53e8d0560','2026-11-04T00:01:14+00:00','2026-11-07T00:01:37+00:00','2026-11-04T00:01:14+00:00');
